  #[using="cs E BUDGET LENMAX GAP"] Lemma win_nolazy : forall lo hi, lo mod 4096 = 0 -> hi mod 4096 = 0 ->
    (forall q, In q (m_vm_lazy model) -> bv_unsigned (fst q) + bv_unsigned (snd q) <= lo \/ hi <= bv_unsigned (fst q)) ->
